using System;using System.IO;using System.Linq;using UnityEditor;using UnityEngine;using UnityEngine.Profiling;using Newtonsoft.Json.Linq;
public static class OptimizeHudTextureMemory {
 public static string Main(bool apply=false){if(Application.isPlaying)throw new Exception("Edit required");var rows=new JArray();foreach(var id in AssetDatabase.FindAssets("t:Texture2D",new[]{"Assets/EternalSteam/Shared/UI"})){var path=AssetDatabase.GUIDToAssetPath(id);var importer=AssetImporter.GetAtPath(path) as TextureImporter;if(importer==null)continue;var t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);var before=Profiler.GetRuntimeMemorySizeLong(t);bool readable=importer.isReadable;if(apply&&readable){importer.isReadable=false;importer.SaveAndReimport();t=AssetDatabase.LoadAssetAtPath<Texture2D>(path);}rows.Add(new JObject{{"path",path},{"width",t.width},{"height",t.height},{"wasReadable",readable},{"isReadable",t.isReadable},{"beforeBytes",before},{"afterBytes",Profiler.GetRuntimeMemorySizeLong(t)}});}Directory.CreateDirectory("Docs/Measurements/2026-10-03-performance");File.WriteAllText("Docs/Measurements/2026-10-03-performance/texture-"+(apply?"after":"before")+".json",rows.ToString());return $"{rows.Count} HUD textures inspected";}
}
